parameters.query:
update public.payments set status = 'overdue'
where status = 'pending' and due_date < current_date
returning id;

parameters.jsCode:
const r = $json;
let text;
// Recordatorio programado a mano (kind='custom'): el texto ya viene escrito y se
// envia literal. Es lo que permite programar un mensaje para una fecha y hora
// concretas sin que sea una cobranza.
if (r.message_text) {
  return [{ json: { ...r, message_text: r.message_text } }];
}
if (r.kind === 'payment_due') {
  const amountStr = `${r.amount} ${r.currency}`;
  if (r.window_key.startsWith('D-')) {
    text = `Hola ${r.full_name || ''}, te recordamos que tienes un pago de ${amountStr} de tu póliza ${r.policy_number || ''} (${r.insurer_name || ''}) con vencimiento el ${r.due_date}. Cualquier duda, aquí estamos.`;
  } else {
    text = `Hola ${r.full_name || ''}, tu pago de ${amountStr} de la póliza ${r.policy_number || ''} (${r.insurer_name || ''}) venció el ${r.due_date}. Escríbenos para coordinar el pago y evitar que tu cobertura se vea afectada.`;
  }
} else if (r.kind === 'policy_renewal') {
  text = `Hola ${r.full_name || ''}, tu póliza ${r.policy_number || ''} (${r.insurer_name || ''}) vence el ${r.end_date}. Contáctanos para gestionar tu renovación a tiempo.`;
} else {
  text = `Hola ${r.full_name || ''}, tienes un recordatorio pendiente. Contáctanos para más detalles.`;
}
return [{ json: { ...r, message_text: text } }];
